using BrewNest.Contracts.Returns;using BrewNest.Modules.Returns.Application.Services;using BrewNest.Modules.Returns.Domain.BusinessRules;using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Routing;
namespace BrewNest.Modules.Returns.Endpoints;
internal static class ReturnsEndpoints
{public static IEndpointRouteBuilder MapReturns(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/returns").WithTags("Returns").RequireAuthorization();g.MapGet("/requests",(ReturnsService s,CancellationToken t)=>Run(s.GetReturns(t))).RequireAuthorization(ReturnsPermissions.Read);g.MapPost("/requests",(CreateReturnRequest r,HttpContext h,ReturnsService s,CancellationToken t)=>Run(s.CreateReturn(r,ReturnsContext.From(h),t))).RequireAuthorization(ReturnsPermissions.Manage);g.MapPost("/requests/{id:guid}/decision",(Guid id,ReturnDecisionRequest r,HttpContext h,ReturnsService s,CancellationToken t)=>Run(s.DecideReturn(id,r,ReturnsContext.From(h),t))).RequireAuthorization(ReturnsPermissions.Approve);g.MapPost("/requests/{id:guid}/lines/{lineId:guid}/inspection",(Guid id,Guid lineId,InspectReturnLineRequest r,HttpContext h,ReturnsService s,CancellationToken t)=>Run(s.Inspect(id,lineId,r,ReturnsContext.From(h),t))).RequireAuthorization(ReturnsPermissions.Inspect);g.MapGet("/voids",(ReturnsService s,CancellationToken t)=>Run(s.GetVoids(t))).RequireAuthorization(ReturnsPermissions.Read);g.MapPost("/voids",(CreateVoidRequest r,HttpContext h,ReturnsService s,CancellationToken t)=>Run(s.CreateVoid(r,ReturnsContext.From(h),t))).RequireAuthorization(ReturnsPermissions.Voids);g.MapPost("/voids/{id:guid}/decision",(Guid id,ReturnDecisionRequest r,HttpContext h,ReturnsService s,CancellationToken t)=>Run(s.DecideVoid(id,r,ReturnsContext.From(h),t))).RequireAuthorization(ReturnsPermissions.VoidsApprove);g.MapGet("/status-history",(ReturnsService s,CancellationToken t)=>Run(s.GetHistory(t))).RequireAuthorization(ReturnsPermissions.Read);return e;}private static async Task<IResult> Run<T>(Task<ReturnsResult<T>> task){var r=await task;if(r.Succeeded)return Results.Ok(r.Value);var(code,title)=r.Status switch{ReturnsResultStatus.Validation=>(400,"Returns validation failed"),ReturnsResultStatus.NotFound=>(404,"Returns record not found"),ReturnsResultStatus.Conflict=>(409,"Returns conflict"),ReturnsResultStatus.Forbidden=>(403,"Returns approval denied"),_=>(500,"Returns operation failed")};return Results.Problem(statusCode:code,title:title,detail:string.Join(' ',r.Errors),extensions:new Dictionary<string,object?>{{"errors",r.Errors}});}}
